// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    Reverter reverter;

    function setUp() public {
        c = new ReentrancyDAO();
        reverter = new Reverter();
    }

    function testFuzz_property(uint256 amount, address depositor) public {
        vm.assume(depositor != address(0) && depositor != address(c) && depositor != address(reverter) && depositor != address(this));
        amount = bound(amount, 0, type(uint256).max / 2);

        // Some arbitrary account may deposit any amount; the reverter itself has ZERO credit.
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Adversarial counterparty with zero credit calls withdrawAll.
        vm.prank(address(reverter));
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: withdrawing with zero credit must never revert.
        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
